function [ch, cd] = rotor_counts(h, delta, s)
%ROTOR_COUNTS  A rotor's momentum h and its gimbal's angle delta as its telemetry's counts.
%   h: real[N m s] (passed in m^2 kg/s)
%   delta: real[rad] (passed a plain number)
%   s: EmuScale (passed rec)
%   returns ch: int (passed a whole number)
%   returns cd: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ch = 0;
    cd = 0;
    ch = asils.models.emucodec.emu_count((h / s.h), s.lo32, s.hi32);
    cd = asils.models.emucodec.emu_count((delta / s.delta), s.lo32, s.hi32);
end
